      if(prefersReduced){items.forEach(function(i){i.classList.add('visible')});return}
      if('IntersectionObserver' in window){ var obs = new IntersectionObserver(function(entries){ entries.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('visible'); obs.unobserve(e.target) } }) },{threshold:0.12}); items.forEach(function(i){obs.observe(i)});
